import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function createTask(server: Running, title: string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const body = (await response.json()) as { tasks: Task[] };
  return body.tasks;
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: open tasks added as A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the list reads C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        // Spaced out so that created_at differs and the order cannot come from the id alone.
        await createTask(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      const tasks = await listTasks(server);
      assert.deepEqual(
        tasks.map((task) => task.title),
        ["C", "B", "A"],
      );
    });
  });

  describe("AC-2: tasks created within the same instant", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: the one saved last is listed first, every time", async () => {
      const titles = Array.from({ length: 30 }, (_, index) => `T${index}`);
      for (const title of titles) await createTask(server, title);

      const tasks = await listTasks(server);
      const sameInstant = new Set(tasks.map((task) => task.created_at)).size < tasks.length;
      assert.ok(sameInstant, "expected at least two tasks to share a created_at");

      for (let round = 0; round < 3; round++) {
        assert.deepEqual(
          (await listTasks(server)).map((task) => task.title),
          [...titles].reverse(),
        );
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the API answers 200 with no tasks", async () => {
      assert.deepEqual(await listTasks(server), []);
    });

    it("AC-3: the page has an empty-state element, hidden until the script shows it", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])(?=[^>]*\bhidden\b)[^>]*>\s*\S/);
    });

    it("AC-3: the page script toggles the empty state on the number of tasks", () => {
      assert.match(script, /empty-state/);
      assert.match(script, /tasks\.length/);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
      for (let batch = 0; batch < 20; batch++) {
        await Promise.all(
          Array.from({ length: 50 }, (_, index) =>
            createTask(server, `Task number ${batch * 50 + index} with a realistic title`),
          ),
        );
      }
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: GET /api/tasks p95 is under 100 ms and the body under 400000 bytes", async () => {
      const durations: number[] = [];
      let bytes = 0;
      let count = 0;
      for (let request = 0; request < 20; request++) {
        const started = performance.now();
        const response = await fetch(`${server.baseUrl}/api/tasks`);
        const text = await response.text();
        durations.push(performance.now() - started);
        bytes = Buffer.byteLength(text);
        count = (JSON.parse(text) as { tasks: Task[] }).tasks.length;
      }
      durations.sort((a, b) => a - b);
      const p95 = durations[Math.ceil(durations.length * 0.95) - 1];

      assert.equal(count, 1000);
      assert.ok(bytes < 400000, `body was ${bytes} bytes`);
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
    });
  });
});
EOF
